package net.officefloor.hq.app.claim;

/** The check, shared by an add and an edit, that a correction names a SETTLED claim of the same person. */
final class RefuseInvalidCorrection {

    private RefuseInvalidCorrection() {
    }

    static void refuse(ClaimInput input, String sheetId, long personId, Claims claims) throws InvalidClaimException {
        if (input.corrects() == null) {
            return;
        }
        Claim corrected = claims.findByNumber(sheetId, personId, input.corrects());
        if (corrected == null || corrected.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimException(
                    "A correction must name a settled claim of the same person: " + input.corrects() + " is not one.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class RefuseInvalidCorrectionClaim {
    // A claim edited into a correction must name, by number, a SETTLED claim of its own person.
    public void refuse(@Val ClaimInput input, @Val Claim claim, Claims claims) throws InvalidClaimException {
        RefuseInvalidCorrection.refuse(input, claim.sheetId(), claim.personId(), claims);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

public class RefuseInvalidCorrectionInput {
    // A correction being added must name, by number, a SETTLED claim of the person it is added to.
    public void refuse(@Val ClaimInput input, @Val Person person, Claims claims) throws InvalidClaimException {
        RefuseInvalidCorrection.refuse(input, person.sheetId(), person.id(), claims);
    }
}
